  '.ico': 'image/x-icon',
};

fs.mkdirSync(path.join(DATA_DIR, 'sessions'), { recursive: true });

// ---------- helpers ----------

function send(res, status, body, type) {
  const buf = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': type || (typeof body === 'object' && !Buffer.isBuffer(body) ? MIME['.json'] : 'text/plain; charset=utf-8'),
    'Content-Length': Buffer.byteLength(buf),
    'Cache-Control': 'no-store',
  });
  res.end(buf);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error('body too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

// Session ids and file names come from the network: never let them escape DATA_DIR.
function safeSessionDir(sessionId) {
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(sessionId)) return null;
  return path.join(DATA_DIR, 'sessions', sessionId);
}

function safeJoin(base, rel) {
  const p = path.normalize(path.join(base, rel));
  if (!p.startsWith(base + path.sep) && p !== base) return null;
  return p;
}

// One streaming pass over the transcript to build the session card shown in the list.
function summarizeTranscript(buf) {
  const meta = {
    title: null,
    customTitle: null,
    firstTimestamp: null,
    lastTimestamp: null,
    firstUserPrompt: null,
    counts: {},
    compactBoundaries: 0,
    cliVersion: null,
    cwd: null,
    gitBranch: null,
    lineCount: 0,
    bytes: buf.length,
  };
  const text = buf.toString('utf8');
  let start = 0;
  while (start < text.length) {
    let end = text.indexOf('\n', start);
    if (end === -1) end = text.length;
    const line = text.slice(start, end).trim();
    start = end + 1;
    if (!line) continue;
    meta.lineCount++;
    let rec;
    try { rec = JSON.parse(line); } catch { continue; }
    meta.counts[rec.type] = (meta.counts[rec.type] || 0) + 1;
    if (rec.timestamp) {
      if (!meta.firstTimestamp) meta.firstTimestamp = rec.timestamp;
      meta.lastTimestamp = rec.timestamp;
    }
    if (rec.type === 'ai-title' && rec.title) meta.title = rec.title;
    if (rec.type === 'custom-title' && rec.title) meta.customTitle = rec.title;
    if (rec.type === 'system' && rec.subtype === 'compact_boundary') meta.compactBoundaries++;
    if (rec.type === 'user' && !meta.firstUserPrompt && !rec.isCompactSummary && rec.message) {
      const c = rec.message.content;
      const s = typeof c === 'string' ? c : Array.isArray(c) ? c.filter((b) => b.type === 'text').map((b) => b.text).join(' ') : '';
      if (s && !s.startsWith('<')) meta.firstUserPrompt = s.slice(0, 300);
    }
    if (!meta.cliVersion && rec.version) meta.cliVersion = rec.version;
    if (!meta.cwd && rec.cwd) meta.cwd = rec.cwd;
    if (rec.gitBranch) meta.gitBranch = rec.gitBranch;
  }
  return meta;
}

async function listSessions() {
  const root = path.join(DATA_DIR, 'sessions');
  const out = [];
  for (const id of await fsp.readdir(root)) {
    const dir = path.join(root, id);
    try {
      const st = await fsp.stat(dir);
      if (!st.isDirectory()) continue;
      let meta = {};
      try { meta = JSON.parse(await fsp.readFile(path.join(dir, 'meta.json'), 'utf8')); } catch {}
      let snapshots = [];
      try { snapshots = (await fsp.readdir(path.join(dir, 'snapshots'))).filter((f) => f.endsWith('.json')); } catch {}
      let files = [];
      try { files = await walkFiles(path.join(dir, 'files')); } catch {}
      out.push({ sessionId: id, ...meta, snapshotCount: snapshots.length, fileCount: files.length });
    } catch {}
  }
  out.sort((a, b) => String(b.importedAt || '').localeCompare(String(a.importedAt || '')));
  return out;
}

async function walkFiles(dir, prefix = '') {
  const out = [];
  for (const ent of await fsp.readdir(dir, { withFileTypes: true })) {
    const rel = prefix ? `${prefix}/${ent.name}` : ent.name;
    if (ent.isDirectory()) out.push(...(await walkFiles(path.join(dir, ent.name), rel)));
    else out.push(rel);
  }
  return out;
}

// ---------- routing ----------

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const p = url.pathname;

    if (p === '/api/health') return send(res, 200, { ok: true, version: 1 });

    if (p.startsWith('/api/import/') && req.method === 'POST') {
      const sessionId = url.searchParams.get('session') || '';
      const dir = safeSessionDir(sessionId);
      if (!dir) return send(res, 400, { error: 'invalid or missing session id' });
      const body = await readBody(req);
      if (!body.length) return send(res, 400, { error: 'empty body' });

      if (p === '/api/import/transcript') {
        await fsp.mkdir(dir, { recursive: true });
        await fsp.writeFile(path.join(dir, 'transcript.jsonl'), body);
        const meta = summarizeTranscript(body);
        meta.project = url.searchParams.get('project') || null;
        meta.importedAt = new Date().toISOString();
        await fsp.writeFile(path.join(dir, 'meta.json'), JSON.stringify(meta, null, 2));
        return send(res, 200, { ok: true, sessionId, ...meta });
      }

      if (p === '/api/import/snapshot') {
        let snap;
        try { snap = JSON.parse(body.toString('utf8')); } catch { return send(res, 400, { error: 'snapshot must be valid JSON' }); }
        snap.receivedAt = new Date().toISOString();
        const name = `snapshot-${snap.receivedAt.replace(/[:.]/g, '-')}.json`;
        await fsp.mkdir(path.join(dir, 'snapshots'), { recursive: true });
        await fsp.writeFile(path.join(dir, 'snapshots', name), JSON.stringify(snap, null, 2));
        return send(res, 200, { ok: true, sessionId, snapshot: name });
      }

      if (p === '/api/import/file') {
        const name = url.searchParams.get('name') || '';
        const filesDir = path.join(dir, 'files');
        const dest = safeJoin(filesDir, name);
        if (!name || !dest) return send(res, 400, { error: 'invalid file name' });
        await fsp.mkdir(path.dirname(dest), { recursive: true });
        await fsp.writeFile(dest, body);
        return send(res, 200, { ok: true, sessionId, file: name, bytes: body.length });
      }
      return send(res, 404, { error: 'unknown import endpoint' });
    }

    if (p === '/api/sessions' && req.method === 'GET') {
      return send(res, 200, await listSessions());
    }

    const m = p.match(/^\/api\/sessions\/([^/]+)(\/.*)?$/);
    if (m) {
      const dir = safeSessionDir(m[1]);
      if (!dir || !fs.existsSync(dir)) return send(res, 404, { error: 'session not found' });
      const rest = m[2] || '';

      if (req.method === 'DELETE' && !rest) {
        await fsp.rm(dir, { recursive: true, force: true });
        return send(res, 200, { ok: true });
      }
      if (rest === '/transcript') {
        return send(res, 200, await fsp.readFile(path.join(dir, 'transcript.jsonl')), MIME['.jsonl']);
      }
      if (rest === '' || rest === '/') {
        let meta = {};
        try { meta = JSON.parse(await fsp.readFile(path.join(dir, 'meta.json'), 'utf8')); } catch {}
        let snapshots = [];
        try { snapshots = (await fsp.readdir(path.join(dir, 'snapshots'))).filter((f) => f.endsWith('.json')).sort(); } catch {}
        let files = [];
        try { files = await walkFiles(path.join(dir, 'files')); } catch {}
        return send(res, 200, { sessionId: m[1], ...meta, snapshots, files });
      }
      if (rest.startsWith('/snapshots/')) {
        const f = safeJoin(path.join(dir, 'snapshots'), rest.slice('/snapshots/'.length));
        if (!f || !fs.existsSync(f)) return send(res, 404, { error: 'snapshot not found' });
        return send(res, 200, await fsp.readFile(f), MIME['.json']);
      }
      if (rest.startsWith('/files/')) {
        const f = safeJoin(path.join(dir, 'files'), decodeURIComponent(rest.slice('/files/'.length)));
        if (!f || !fs.existsSync(f)) return send(res, 404, { error: 'file not found' });
        return send(res, 200, await fsp.readFile(f), MIME[path.extname(f)] || 'text/plain; charset=utf-8');
      }
      return send(res, 404, { error: 'not found' });
    }

    // static SPA
    if (req.method === 'GET') {
      let rel = p === '/' ? '/index.html' : p;
      const f = safeJoin(PUBLIC_DIR, rel);
      if (f && fs.existsSync(f) && fs.statSync(f).isFile()) {
        return send(res, 200, await fsp.readFile(f), MIME[path.extname(f)] || 'application/octet-stream');
      }
      // hash-routed SPA: any other GET falls through to the shell
      return send(res, 200, await fsp.readFile(path.join(PUBLIC_DIR, 'index.html')), MIME['.html']);
    }

    return send(res, 405, { error: 'method not allowed' });
  } catch (err) {
    send(res, err.status || 500, { error: String(err.message || err) });
  }
});

server.listen(PORT, HOST, () => {
  console.log(`Context Explorer listening on http://${HOST}:${PORT} (data: ${DATA_DIR})`);
});

input.content:
/* Context Explorer — flight recorder for the context window.
   Dark instrument panel; validated categorical palette (dataviz six checks, dark surface #14181f):
   user #4a8fdd · attachment #27a578 · assistant #c08618 · tool/sidechain #8a5fe8 · event/compact #d75d84 */

:root {
  --bg: #14181f;
  --panel: #1b2029;
  --panel-2: #222834;
  --line: #2e3542;
  --ink: #dfe4ec;
  --muted: #8b94a7;
  --faint: #5d6577;
  --accent: #f0b429;        /* chrome accent — amber phosphor */
  --k-user: #4a8fdd;
  --k-attach: #27a578;
  --k-assistant: #c08618;
  --k-tool: #8a5fe8;
  --k-event: #d75d84;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --sans: "Avenir Next", "Futura", "Helvetica Neue", system-ui, sans-serif;
}

* { box-sizing: border-box; margin: 0; }
html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.55;
}
.app { position: relative; max-width: 1500px; margin: 0 auto; padding: 0 clamp(14px, 2.5vw, 36px); min-height: 100vh; }
.makers-mark { position: absolute; top: clamp(14px,2.5vw,26px); right: clamp(14px,3vw,30px); width: 30px; height: auto; opacity: .5; z-index: 20; pointer-events: none; }

a { color: var(--k-user); text-decoration: none; }
a:hover { text-decoration: underline; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.eyebrow {
  font-size: 11px; letter-spacing: .18em; text-transform: uppercase;
  color: var(--muted); font-weight: 600;
}

/* ---------- header ---------- */
.masthead { padding: 34px 0 10px; display: flex; align-items: baseline; gap: 18px; flex-wrap: wrap; }
.masthead h1 { font-size: 22px; font-weight: 700; letter-spacing: .30em; text-transform: uppercase; }
.masthead h1 .dim { color: var(--accent); }
.masthead .sub { color: var(--muted); font-size: 13px; }
.crumb { padding: 22px 0 4px; font-size: 13px; color: var(--muted); }

/* ---------- session list ---------- */
.session-list { display: flex; flex-direction: column; gap: 10px; padding: 18px 0 60px; }
.session-card {
  display: block; background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 14px 18px; color: inherit; transition: border-color .15s;
}
.session-card:hover { border-color: var(--accent); text-decoration: none; }
.session-card .row1 { display: flex; gap: 12px; align-items: baseline; flex-wrap: wrap; }
.session-card .title { font-weight: 600; font-size: 16px; }
.session-card .proj { font-family: var(--mono); font-size: 12px; color: var(--k-attach); }
.session-card .prompt { color: var(--muted); font-size: 13px; margin-top: 4px; font-family: var(--mono); }
.session-card .stats { display: flex; gap: 16px; margin-top: 8px; font-size: 12px; color: var(--faint); flex-wrap: wrap; }
.session-card .stats b { color: var(--muted); font-weight: 600; }
.empty-state { padding: 60px 0; color: var(--muted); max-width: 620px; }
.empty-state h2 { color: var(--ink); margin-bottom: 10px; font-size: 18px; }
.empty-state code { font-family: var(--mono); background: var(--panel-2); padding: 2px 7px; border-radius: 4px; font-size: 13px; color: var(--accent); }
.empty-state p { margin: 8px 0; }

/* ---------- the tape (signature instrument) ---------- */
.tape-wrap {
  position: sticky; top: 0; z-index: 10;
  background: var(--bg); padding: 8px 0 4px;
  border-bottom: 1px solid var(--line);
}
.tape-head { display: flex; justify-content: space-between; align-items: baseline; padding-bottom: 4px; gap: 10px; flex-wrap: wrap; }
.tape-head .readout { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.tape-head .readout b { color: var(--accent); font-weight: 600; }
canvas.tape { width: 100%; height: 92px; display: block; cursor: crosshair; border-radius: 6px; background: var(--panel); }
.tape-tip {
  position: fixed; pointer-events: none; z-index: 50; display: none;
  background: var(--panel-2); border: 1px solid var(--line); border-radius: 6px;
  padding: 6px 10px; font-family: var(--mono); font-size: 11.5px; color: var(--ink);
  max-width: 340px; box-shadow: 0 4px 18px rgba(0,0,0,.5);
}
.tape-tip .k { color: var(--muted); }

/* ---------- session layout ---------- */
.session-body { display: grid; grid-template-columns: minmax(300px, 420px) 1fr; gap: 18px; padding: 14px 0 80px; align-items: start; }
@media (max-width: 900px) { .session-body { grid-template-columns: 1fr; } }

.rail { border: 1px solid var(--line); border-radius: 8px; background: var(--panel); overflow: hidden; }
.rail-head { display:flex; justify-content: space-between; align-items:center; padding: 9px 12px; border-bottom: 1px solid var(--line); }
.rail-head label { font-size: 12px; color: var(--muted); display: flex; gap: 6px; align-items: center; cursor: pointer; }
.rail-list { max-height: calc(100vh - 220px); overflow-y: auto; }
.rec {
  display: grid; grid-template-columns: 10px 86px 1fr; gap: 10px; align-items: baseline;
  padding: 6px 12px; cursor: pointer; border-left: 3px solid transparent;
  font-family: var(--mono); font-size: 12.5px;
}
.rec:hover { background: var(--panel-2); }
.rec.sel { background: var(--panel-2); border-left-color: var(--accent); }
.rec .dot { width: 8px; height: 8px; border-radius: 2px; align-self: center; }
.rec .kind { color: var(--muted); font-size: 11px; letter-spacing: .04em; }
.rec .prev { color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rec.sidechain { opacity: .45; }
.rec.ctx-out .prev, .rec.ctx-out .kind { color: var(--faint); }
.rec.compact-row { background: rgba(215,93,132,.08); }

/* ---------- context panel ---------- */
.ctx-panel { min-width: 0; }
.tabs { display: flex; gap: 4px; margin-bottom: 10px; flex-wrap: wrap; }
.tabs button {
  background: var(--panel); color: var(--muted); border: 1px solid var(--line);
  border-radius: 6px; padding: 6px 14px; font: 600 12px var(--sans);
  letter-spacing: .08em; text-transform: uppercase; cursor: pointer;
}
.tabs button.on { color: var(--bg); background: var(--accent); border-color: var(--accent); }
.layer { border: 1px solid var(--line); border-radius: 8px; background: var(--panel); margin-bottom: 12px; overflow: hidden; }
.layer > summary {
  list-style: none; cursor: pointer; padding: 9px 14px;
  display: flex; gap: 10px; align-items: baseline;
}
.layer > summary::-webkit-details-marker { display: none; }
.layer > summary:hover { background: var(--panel-2); }
.layer > summary .badge { margin-left: auto; font-family: var(--mono); font-size: 11px; color: var(--faint); }
.layer .body { border-top: 1px solid var(--line); padding: 12px 14px; }
.layer .note { font-size: 12px; color: var(--faint); font-style: italic; margin-bottom: 8px; }
pre.block {
  font-family: var(--mono); font-size: 12.5px; line-height: 1.5; color: var(--ink);
  white-space: pre-wrap; word-break: break-word;
  background: var(--bg); border: 1px solid var(--line); border-radius: 6px;
  padding: 10px 12px; overflow-x: auto; max-height: 480px; overflow-y: auto;
}
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 3px 16px; font-family: var(--mono); font-size: 12.5px; }
.kv .k { color: var(--muted); }
.gauge { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.gauge .num { font-family: var(--mono); font-size: 26px; font-weight: 700; color: var(--accent); }
.gauge .parts { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.chiplist { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { font-family: var(--mono); font-size: 11.5px; background: var(--bg); border: 1px solid var(--line); border-radius: 999px; padding: 2px 10px; color: var(--ink); }
.chip.new { border-color: var(--k-attach); color: var(--k-attach); }

/* message thread inside context tab */
.msg { border: 1px solid var(--line); border-radius: 8px; margin-bottom: 8px; overflow: hidden; background: var(--panel); }
.msg > summary { list-style: none; cursor: pointer; padding: 7px 12px; display: flex; gap: 10px; align-items: baseline; font-family: var(--mono); font-size: 12.5px; }
.msg > summary::-webkit-details-marker { display: none; }
.msg > summary .role { font-weight: 700; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; }
.msg > summary .prev { color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; flex: 1; }
.msg .body { border-top: 1px solid var(--line); padding: 10px 12px; }
.msg.m-user > summary .role { color: var(--k-user); }
.msg.m-assistant > summary .role { color: var(--k-assistant); }
.msg.m-attachment > summary .role { color: var(--k-attach); }
.msg.m-system > summary .role, .msg.m-compact > summary .role { color: var(--k-event); }
.msg.m-tool > summary .role { color: var(--k-tool); }
.blk { margin-bottom: 8px; }
.blk .blk-tag { font-family: var(--mono); font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--faint); margin-bottom: 3px; }

.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
@media (max-width: 1100px) { .two-col { grid-template-columns: 1fr; } }

.pill-select { background: var(--panel-2); color: var(--ink); border: 1px solid var(--line); border-radius: 6px; font: 12px var(--mono); padding: 4px 8px; max-width: 100%; }
.warn { color: var(--k-event); font-size: 12.5px; }
.hint { color: var(--faint); font-size: 12px; }

@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

