/* ---------- the tape (signature instrument) ---------- */
.tape-wrap {
  position: sticky; top: 0; z-index: 10;
  background: var(--bg); padding: 8px 0 4px;
  border-bottom: 1px solid var(--line);
}
.tape-head { display: flex; justify-content: space-between; align-items: baseline; padding-bottom: 4px; gap: 10px; flex-wrap: wrap; }
.tape-head .readout { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.tape-head .readout b { color: var(--accent); font-weight: 600; }
canvas.tape { width: 100%; height: 92px; display: block; cursor: crosshair; border-radius: 6px; background: var(--panel); }
.tape-tip {
  position: fixed; pointer-events: none; z-index: 50; display: none;
  background: var(--panel-2); border: 1px solid var(--line); border-radius: 6px;
  padding: 6px 10px; font-family: var(--mono); font-size: 11.5px; color: var(--ink);
  max-width: 340px; box-shadow: 0 4px 18px rgba(0,0,0,.5);
}
.tape-tip .k { color: var(--muted); }

/* ---------- session layout ---------- */
.session-body { display: grid; grid-template-columns: minmax(300px, 420px) 1fr; gap: 18px; padding: 14px 0 80px; align-items: start; }
@media (max-width: 900px) { .session-body { grid-template-columns: 1fr; } }

.rail { border: 1px solid var(--line); border-radius: 8px; background: var(--panel); overflow: hidden; }
.rail-head { display:flex; justify-content: space-between; align-items:center; padding: 9px 12px; border-bottom: 1px solid var(--line); }
.rail-head label { font-size: 12px; color: var(--muted); display: flex; gap: 6px; align-items: center; cursor: pointer; }
.rail-list { max-height: calc(100vh - 220px); overflow-y: auto; }
.rec {
  display: grid; grid-template-columns: 10px 86px 1fr; gap: 10px; align-items: baseline;
  padding: 6px 12px; cursor: pointer; border-left: 3px solid transparent;
  font-family: var(--mono); font-size: 12.5px;
}
.rec:hover { background: var(--panel-2); }
.rec.sel { background: var(--panel-2); border-left-color: var(--accent); }
.rec .dot { width: 8px; height: 8px; border-radius: 2px; align-self: center; }
.rec .kind { color: var(--muted); font-size: 11px; letter-spacing: .04em; }
.rec .prev { color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rec.sidechain { opacity: .45; }
.rec.ctx-out .prev, .rec.ctx-out .kind { color: var(--faint); }
.rec.compact-row { background: rgba(215,93,132,.08); }

/* ---------- context panel ---------- */
.ctx-panel { min-width: 0; }
.tabs { display: flex; gap: 4px; margin-bottom: 10px; flex-wrap: wrap; }
.tabs button {
  background: var(--panel); color: var(--muted); border: 1px solid var(--line);
  border-radius: 6px; padding: 6px 14px; font: 600 12px var(--sans);
  letter-spacing: .08em; text-transform: uppercase; cursor: pointer;
}
.tabs button.on { color: var(--bg); background: var(--accent); border-color: var(--accent); }
.layer { border: 1px solid var(--line); border-radius: 8px; background: var(--panel); margin-bottom: 12px; overflow: hidden; }
.layer > summary {
  list-style: none; cursor: pointer; padding: 9px 14px;
  display: flex; gap: 10px; align-items: baseline;
}
.layer > summary::-webkit-details-marker { display: none; }
.layer > summary:hover { background: var(--panel-2); }
.layer > summary .badge { margin-left: auto; font-family: var(--mono); font-size: 11px; color: var(--faint); }
.layer .body { border-top: 1px solid var(--line); padding: 12px 14px; }
.layer .note { font-size: 12px; color: var(--faint); font-style: italic; margin-bottom: 8px; }
pre.block {
  font-family: var(--mono); font-size: 12.5px; line-height: 1.5; color: var(--ink);
  white-space: pre-wrap; word-break: break-word;
  background: var(--bg); border: 1px solid var(--line); border-radius: 6px;
  padding: 10px 12px; overflow-x: auto; max-height: 480px; overflow-y: auto;
}
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 3px 16px; font-family: var(--mono); font-size: 12.5px; }
.kv .k { color: var(--muted); }
.gauge { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.gauge .num { font-family: var(--mono); font-size: 26px; font-weight: 700; color: var(--accent); }
.gauge .parts { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.chiplist { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { font-family: var(--mono); font-size: 11.5px; background: var(--bg); border: 1px solid var(--line); border-radius: 999px; padding: 2px 10px; color: var(--ink); }
.chip.new { border-color: var(--k-attach); color: var(--k-attach); }

/* message thread inside context tab */
.msg { border: 1px solid var(--line); border-radius: 8px; margin-bottom: 8px; overflow: hidden; background: var(--panel); }
.msg > summary { list-style: none; cursor: pointer; padding: 7px 12px; display: flex; gap: 10px; align-items: baseline; font-family: var(--mono); font-size: 12.5px; }
.msg > summary::-webkit-details-marker { display: none; }
.msg > summary .role { font-weight: 700; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; }
.msg > summary .prev { color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; flex: 1; }
.msg .body { border-top: 1px solid var(--line); padding: 10px 12px; }
.msg.m-user > summary .role { color: var(--k-user); }
.msg.m-assistant > summary .role { color: var(--k-assistant); }
.msg.m-attachment > summary .role { color: var(--k-attach); }
.msg.m-system > summary .role, .msg.m-compact > summary .role { color: var(--k-event); }
.msg.m-tool > summary .role { color: var(--k-tool); }
.blk { margin-bottom: 8px; }
.blk .blk-tag { font-family: var(--mono); font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--faint); margin-bottom: 3px; }

.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
@media (max-width: 1100px) { .two-col { grid-template-columns: 1fr; } }

.pill-select { background: var(--panel-2); color: var(--ink); border: 1px solid var(--line); border-radius: 6px; font: 12px var(--mono); padding: 4px 8px; max-width: 100%; }
.warn { color: var(--k-event); font-size: 12.5px; }
.hint { color: var(--faint); font-size: 12px; }

@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

input.content:
/* Context Explorer SPA — parses raw session JSONL client-side and reconstructs
   the effective context window at any selected record.
   Reconstruction rules (derived from real Claude Code transcripts):
   - records link via parentUuid: context-at-point = parent-chain walk to root
   - compact_boundary records have parentUuid null, so the chain walk naturally
     stops at the live context's edge after a compaction
   - isSidechain records are subagent turns; never part of the main context
   - attachment kinds have different semantics: deferred_tools_delta accumulates,
     skill_listing / output_style / agent_listing supersede, mcp_instructions accumulates */
'use strict';

const KIND_COLORS = {
  user: '#4a8fdd',
  assistant: '#c08618',
  tool: '#8a5fe8',
  attach: '#27a578',
  event: '#d75d84',
};
const KIND_LABELS = { user: 'user', assistant: 'assistant', tool: 'tool i/o', attach: 'context Δ', event: 'event' };
const ACCENT = '#f0b429';

const $view = document.getElementById('view');
const state = { sessions: null, session: null };

// ---------- utilities ----------

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmtInt = (n) => (n == null ? '—' : Number(n).toLocaleString('en-US'));
const fmtTime = (ts) => (ts ? new Date(ts).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '—');
const el = (html) => { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstElementChild; };

async function jget(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  return r.json();
}
async function tget(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  return r.text();
}

// ---------- transcript model ----------

function parseTranscript(jsonl) {
  const records = [];
  for (const line of jsonl.split('\n')) {
    const t = line.trim();
    if (!t) continue;
    try { records.push(JSON.parse(t)); } catch { /* tolerate partial lines */ }
  }
  // content records: things that occupy (or mark the edge of) the context window
  const content = records.filter((r) =>
    r.type === 'user' || r.type === 'assistant' || r.type === 'attachment' ||
    (r.type === 'system' && r.subtype !== 'turn_duration'));
  const byUuid = new Map();
  for (const r of records) if (r.uuid) byUuid.set(r.uuid, r);
  return { records, content, byUuid };
}

function recKind(r) {
  if (r.type === 'attachment') return 'attach';
  if (r.type === 'system') return 'event';
  if (r.type === 'assistant') {
    const blocks = Array.isArray(r.message?.content) ? r.message.content : [];
    return blocks.length && blocks.every((b) => b.type === 'tool_use') ? 'tool' : 'assistant';
  }
  if (r.type === 'user') {
    const c = r.message?.content;
    if (Array.isArray(c) && c.length && c.every((b) => b.type === 'tool_result')) return 'tool';
    return 'user';
  }
  return 'event';
}

function recPreview(r) {
  if (r.type === 'attachment') {
    const a = r.attachment || {};
    if (a.type === 'deferred_tools_delta') return `deferred tools ${a.addedNames ? '+' + a.addedNames.length : ''}`;
    if (a.type === 'skill_listing') return `skill listing (${a.skillCount ?? '?'} skills)`;
    return a.type || 'attachment';
  }
  if (r.type === 'system') {
    if (r.subtype === 'compact_boundary') {
      const m = r.compactMetadata || {};
      return `COMPACTION ${fmtInt(m.preTokens)} → ${fmtInt(m.postTokens)} tok (${m.trigger || '?'})`;
    }
    return `${r.subtype || 'system'}: ${String(r.content ?? '').slice(0, 120)}`;
  }
  const c = r.message?.content;
  if (typeof c === 'string') return c.slice(0, 160);
  if (Array.isArray(c)) {
    for (const b of c) {
      if (b.type === 'text' && b.text) return b.text.slice(0, 160);
      if (b.type === 'tool_use') return `→ ${b.name}(${JSON.stringify(b.input ?? {}).slice(0, 110)})`;
      if (b.type === 'tool_result') {
        const inner = typeof b.content === 'string' ? b.content : Array.isArray(b.content) ? b.content.map((x) => x.text || '').join(' ') : '';
        return `← ${String(inner).slice(0, 150)}`;
      }
      if (b.type === 'thinking') return `[thinking] ${String(b.thinking || '').slice(0, 140)}`;
    }
  }
  return r.type;
}

function usageOf(r) {
  const u = r.message?.usage;
  if (!u) return null;
  const ctx = (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0);
  return { ctx, out: u.output_tokens || 0, u };
}

/* Effective context chain at a content record: walk parentUuid to root.
   Returns { chain, boundary } where boundary is the compact_boundary reached, if any. */
function chainAt(model, rec) {
  let start = rec;
  // meta/system rows without a chain link: anchor to the nearest prior linked record
  const idx = model.content.indexOf(rec);
  let i = idx;
  while (start && !start.uuid && i > 0) start = model.content[--i];
  const chain = [];
  const seen = new Set();
  let cur = start;
  while (cur && cur.uuid && !seen.has(cur.uuid)) {
    seen.add(cur.uuid);
    if (!cur.isSidechain) chain.push(cur);
    cur = cur.parentUuid ? model.byUuid.get(cur.parentUuid) : null;
  }
  chain.reverse();
  const boundary = chain.find((r) => r.type === 'system' && r.subtype === 'compact_boundary') || null;
  return { chain, boundary };
}

/* Session-lifetime attachment state accumulated chronologically up to (and incl.) index. */
function stateAt(model, idx) {
  const s = { deferredTools: new Set(), skillListing: null, mcpInstructions: [], outputStyle: null, agentListing: null, other: [] };
  for (let i = 0; i <= idx; i++) {
    const r = model.content[i];
    if (r.type !== 'attachment') continue;
    const a = r.attachment || {};
    switch (a.type) {
      case 'deferred_tools_delta':
        (a.addedNames || []).forEach((n) => s.deferredTools.add(n));
        (a.removedNames || []).forEach((n) => s.deferredTools.delete(n));
        break;
      case 'skill_listing': s.skillListing = a; break;
      case 'mcp_instructions_delta': s.mcpInstructions.push(a); break;
      case 'output_style': s.outputStyle = a; break;
      case 'agent_listing_delta': s.agentListing = a; break;
      default: s.other.push(a);
    }
  }
  return s;
}

/* Nearest assistant usage at-or-before index → context size readout. */
function tokensAt(model, idx) {
  for (let i = idx; i >= 0; i--) {
    const u = usageOf(model.content[i]);
    if (u) return { ...u, at: i };
  }
  return null;
}

// ---------- router ----------

window.addEventListener('hashchange', route);
route();

async function route() {
  const h = location.hash || '#/';
  try {
    const m = h.match(/^#\/s\/([A-Za-z0-9_-]+)/);
    if (m) await sessionView(m[1]);
    else await homeView();
  } catch (err) {
    $view.innerHTML = `<div class="empty-state"><h2>Something broke</h2><p class="warn">${esc(err.message)}</p></div>`;
  }
}

// ---------- home ----------

async function homeView() {
  document.title = 'Context Explorer';
  const sessions = await jget('/api/sessions');
  const cards = sessions.map((s) => {
    const title = s.customTitle || s.title || s.firstUserPrompt?.slice(0, 80) || s.sessionId;
    return `
    <a class="session-card" href="#/s/${esc(s.sessionId)}">
      <div class="row1">
        <span class="title">${esc(title)}</span>
        <span class="proj">${esc(s.project || s.cwd || '')}</span>
      </div>
      ${s.firstUserPrompt ? `<div class="prompt">${esc(s.firstUserPrompt.slice(0, 160))}</div>` : ''}
      <div class="stats">
        <span><b>${fmtInt(s.lineCount)}</b> records</span>
        <span><b>${fmtInt(s.snapshotCount)}</b> snapshot${s.snapshotCount === 1 ? '' : 's'}</span>
        <span><b>${fmtInt(s.compactBoundaries)}</b> compaction${s.compactBoundaries === 1 ? '' : 's'}</span>
        <span>${esc(fmtTime(s.firstTimestamp))} → ${esc(fmtTime(s.lastTimestamp))}</span>
        <span>cli ${esc(s.cliVersion || '?')}</span>
      </div>
    </a>`;
  }).join('');
  $view.innerHTML = `
    <header class="masthead">
      <h1>Context <span class="dim">Explorer</span></h1>
      <span class="sub">flight recorder for the Claude Code context window</span>
    </header>
    ${sessions.length ? `<div class="session-list">${cards}</div>` : `
    <div class="empty-state">
      <h2>No sessions imported yet</h2>
      <p>In any Claude Code session, run <code>/context-export</code>. The skill ships the
      session transcript here, along with an as-transcribed snapshot of the system prompt
      and loaded tool definitions — the parts that exist only inside the model's context.</p>
      <p>Then refresh this page.</p>
    </div>`}`;
}

// ---------- session ----------

async function sessionView(id) {
  $view.innerHTML = `<div class="crumb">loading transcript…</div>`;
  const [manifest, jsonl] = await Promise.all([
    jget(`/api/sessions/${id}`),
    tget(`/api/sessions/${id}/transcript`),
  ]);
  const model = parseTranscript(jsonl);
  const snapshots = [];
  for (const name of manifest.snapshots || []) {
    try { snapshots.push({ name, data: await jget(`/api/sessions/${id}/snapshots/${name}`) }); } catch {}
  }
  const title = manifest.customTitle || manifest.title || id;
  document.title = `${title} — Context Explorer`;

  const s = {
    id, manifest, model, snapshots,
    sel: model.content.length - 1,
    tab: 'context',
    showSidechain: true,
    snapIdx: snapshots.length - 1,
  };
  state.session = s;

  $view.innerHTML = `
    <div class="crumb"><a href="#/">← sessions</a> &nbsp;/&nbsp; <span style="font-family:var(--mono)">${esc(id)}</span></div>
    <header class="masthead" style="padding-top:6px">
      <h1 style="letter-spacing:.02em;text-transform:none;font-size:19px">${esc(title)}</h1>
      <span class="sub">${esc(manifest.project || manifest.cwd || '')}</span>
    </header>
    <div class="tape-wrap">
      <div class="tape-head">
        <span class="eyebrow">context tape — tokens in window · click to scrub</span>
        <span class="readout" id="readout"></span>
      </div>
      <canvas class="tape" id="tape" aria-label="Session timeline: context tokens per record; click to select a point in time"></canvas>
      <div class="tape-head" id="legend" style="padding-top:4px"></div>
    </div>
    <div class="session-body">
      <div class="rail">
        <div class="rail-head">
          <span class="eyebrow">records (${model.content.length})</span>
          <label><input type="checkbox" id="sidechainToggle" checked> subagent turns</label>
        </div>
        <div class="rail-list" id="rail"></div>
      </div>
      <div class="ctx-panel">
        <div class="tabs" id="tabs"></div>
        <div id="panel"></div>
      </div>
    </div>
    <div class="tape-tip" id="tapeTip"></div>`;

  document.getElementById('legend').innerHTML = Object.keys(KIND_COLORS).map((k) =>
    `<span class="readout"><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:${KIND_COLORS[k]};margin-right:5px"></span>${KIND_LABELS[k]}</span>`).join('') +
    `<span class="readout"><span style="display:inline-block;width:2px;height:11px;background:${KIND_COLORS.event};margin-right:5px"></span>compaction splice</span>`;

  document.getElementById('sidechainToggle').addEventListener('change', (e) => {
    s.showSidechain = e.target.checked;
    renderRail(s);
  });

  renderRail(s);
  initTape(s);
  select(s, s.sel, { scrollRail: true });
  window.addEventListener('resize', () => drawTape(s), { passive: true });
}

function select(s, idx, opts = {}) {
  s.sel = Math.max(0, Math.min(idx, s.model.content.length - 1));
  const rec = s.model.content[s.sel];
  // choose snapshot: latest whose exportedAt <= selected record time, else earliest after
  if (s.snapshots.length && !opts.keepSnap) {
    const t = rec.timestamp ? Date.parse(rec.timestamp) : Infinity;
    let pick = 0;
    s.snapshots.forEach((sn, i) => {
      const ts = Date.parse(sn.data.exportedAt || sn.data.receivedAt || 0);
      if (ts <= t || i === 0) pick = i;
    });
    s.snapIdx = pick;
  }
  document.querySelectorAll('.rec.sel').forEach((n) => n.classList.remove('sel'));
  const row = document.querySelector(`.rec[data-i="${s.sel}"]`);
  if (row) {
    row.classList.add('sel');
    if (opts.scrollRail) row.scrollIntoView({ block: 'center' });
  }
  drawTape(s);
  renderTabs(s);
  renderPanel(s);
  const u = tokensAt(s.model, s.sel);
  document.getElementById('readout').innerHTML =
    `rec <b>${s.sel + 1}</b>/${s.model.content.length}` +
    ` · <b>${u ? fmtInt(u.ctx) : '—'}</b> tok in window` +
    ` · ${esc(fmtTime(rec.timestamp))}`;
}

// ---------- record rail ----------

function renderRail(s) {
  const railEl = document.getElementById('rail');
  const frag = document.createDocumentFragment();
  s.model.content.forEach((r, i) => {
    if (r.isSidechain && !s.showSidechain) return;
    const kind = recKind(r);
    const compact = r.type === 'system' && r.subtype === 'compact_boundary';
    const row = el(`<div class="rec${r.isSidechain ? ' sidechain' : ''}${compact ? ' compact-row' : ''}" data-i="${i}" tabindex="0" role="button">
      <span class="dot" style="background:${KIND_COLORS[kind]}"></span>
      <span class="kind">${esc(r.type === 'attachment' ? (r.attachment?.type || 'attach').slice(0, 13) : (r.subtype || r.type))}</span>
      <span class="prev">${esc(recPreview(r))}</span>
    </div>`);
    row.addEventListener('click', () => select(s, i));
    row.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(s, i); } });
    frag.appendChild(row);
  });
  railEl.replaceChildren(frag);
}

// ---------- the tape (canvas instrument) ----------

function initTape(s) {
  const cv = document.getElementById('tape');
  const tip = document.getElementById('tapeTip');
  const idxFromEvent = (e) => {
    const r = cv.getBoundingClientRect();
    return Math.round(((e.clientX - r.left) / r.width) * (s.model.content.length - 1));
  };
  cv.addEventListener('click', (e) => select(s, idxFromEvent(e), { scrollRail: true }));
  cv.addEventListener('mousemove', (e) => {
    const i = Math.max(0, Math.min(idxFromEvent(e), s.model.content.length - 1));
    s.hover = i;
    drawTape(s);
    const rec = s.model.content[i];
    const u = tokensAt(s.model, i);
    tip.style.display = 'block';
    tip.style.left = Math.min(e.clientX + 14, window.innerWidth - 360) + 'px';
    tip.style.top = (e.clientY + 16) + 'px';
    tip.innerHTML = `<span class="k">#${i + 1} ${esc(rec.subtype || rec.type)}</span> · ${u ? fmtInt(u.ctx) + ' tok' : ''}<br>${esc(recPreview(rec).slice(0, 120))}`;
  });
  cv.addEventListener('mouseleave', () => { s.hover = null; tip.style.display = 'none'; drawTape(s); });
}

function drawTape(s) {
  const cv = document.getElementById('tape');
  if (!cv) return;
  const dpr = window.devicePixelRatio || 1;
  const W = cv.clientWidth, H = cv.clientHeight;
  cv.width = W * dpr; cv.height = H * dpr;
  const g = cv.getContext('2d');
  g.scale(dpr, dpr);
  g.clearRect(0, 0, W, H);

  const n = s.model.content.length;
  if (!n) return;
  const x = (i) => (i / Math.max(1, n - 1)) * (W - 8) + 4;
  const stripH = 16, chartH = H - stripH - 6;

  // token series: context size at each assistant record, stepped
  let maxTok = 1;
  const pts = [];
  let last = 0;
  s.model.content.forEach((r, i) => {
    const u = usageOf(r);
    if (u) { last = u.ctx; maxTok = Math.max(maxTok, u.ctx); }
    pts.push(last);
  });
  const y = (t) => chartH - (t / maxTok) * (chartH - 10) + 4;

  // area (single amber series)
  g.beginPath();
  g.moveTo(x(0), y(pts[0]));
  for (let i = 1; i < n; i++) g.lineTo(x(i), y(pts[i]));
  g.lineTo(x(n - 1), chartH + 4); g.lineTo(x(0), chartH + 4); g.closePath();
  g.fillStyle = 'rgba(192,134,24,0.22)';
  g.fill();
  g.beginPath();
  g.moveTo(x(0), y(pts[0]));
  for (let i = 1; i < n; i++) g.lineTo(x(i), y(pts[i]));
  g.strokeStyle = '#c08618'; g.lineWidth = 2; g.stroke();

  // tick strip by kind
  s.model.content.forEach((r, i) => {
    g.fillStyle = KIND_COLORS[recKind(r)];
    g.globalAlpha = r.isSidechain ? 0.35 : 0.9;
    g.fillRect(x(i) - 0.75, H - stripH, 1.5, stripH - 2);
    g.globalAlpha = 1;
  });

  // compaction splices: full-height, with a gap notch (shape = secondary encoding)
  s.model.content.forEach((r, i) => {
    if (r.type === 'system' && r.subtype === 'compact_boundary') {
      g.strokeStyle = KIND_COLORS.event; g.lineWidth = 2;
      g.setLineDash([5, 3]);
      g.beginPath(); g.moveTo(x(i), 2); g.lineTo(x(i), H - 2); g.stroke();
      g.setLineDash([]);
    }
  });

  // hover crosshair
  if (s.hover != null) {
    g.strokeStyle = 'rgba(223,228,236,0.35)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(x(s.hover), 0); g.lineTo(x(s.hover), H); g.stroke();
  }
  // selection cursor
  g.strokeStyle = ACCENT; g.lineWidth = 2;
  g.beginPath(); g.moveTo(x(s.sel), 0); g.lineTo(x(s.sel), H); g.stroke();
  g.fillStyle = ACCENT;
  g.beginPath(); g.moveTo(x(s.sel) - 5, 0); g.lineTo(x(s.sel) + 5, 0); g.lineTo(x(s.sel), 7); g.closePath(); g.fill();
}

// ---------- tabs + panels ----------

function renderTabs(s) {
  const tabs = [
    ['context', 'Context at this point'],
    ['record', 'Record'],
    ['snapshot', `Snapshot${s.snapshots.length ? ` (${s.snapshots.length})` : ''}`],
    ['files', `Files (${(s.manifest.files || []).length})`],
  ];
  document.getElementById('tabs').innerHTML = tabs.map(([k, label]) =>
    `<button data-tab="${k}" class="${s.tab === k ? 'on' : ''}">${label}</button>`).join('');
  document.querySelectorAll('#tabs button').forEach((b) =>
    b.addEventListener('click', () => { s.tab = b.dataset.tab; renderTabs(s); renderPanel(s); }));
}

function layer(title, badge, bodyHtml, open = false) {
  return `<details class="layer"${open ? ' open' : ''}>
    <summary><span class="eyebrow">${title}</span><span class="badge">${badge}</span></summary>
    <div class="body">${bodyHtml}</div>
  </details>`;
}

function renderPanel(s) {
  const panel = document.getElementById('panel');
  if (s.tab === 'record') return renderRecordTab(s, panel);
  if (s.tab === 'snapshot') return renderSnapshotTab(s, panel);
  if (s.tab === 'files') return renderFilesTab(s, panel);
  renderContextTab(s, panel);
}

function renderContextTab(s, panel) {
  const rec = s.model.content[s.sel];
  const { chain, boundary } = chainAt(s.model, rec);
  const st = stateAt(s.model, s.sel);
  const u = tokensAt(s.model, s.sel);
  const snap = s.snapshots[s.snapIdx]?.data;

  const parts = [];

  // token gauge
  parts.push(layer('Context window load', u ? `measured at record ${u.at + 1}` : 'no usage data yet', u ? `
    <div class="gauge">
      <span class="num">${fmtInt(u.ctx)}</span><span class="eyebrow">tokens in window</span>
      <span class="parts">cache-read ${fmtInt(u.u.cache_read_input_tokens)} · cache-write ${fmtInt(u.u.cache_creation_input_tokens)} · fresh in ${fmtInt(u.u.input_tokens)} · out ${fmtInt(u.u.output_tokens)}</span>
    </div>` : '<p class="hint">No assistant turn with usage before this point.</p>', true));

  // system prompt (from snapshot)
  if (snap) {
    const sys = snap.systemPrompt || [];
    const snapSel = s.snapshots.length > 1 ? `<select class="pill-select" id="snapSel">${s.snapshots.map((sn, i) =>
      `<option value="${i}"${i === s.snapIdx ? ' selected' : ''}>${esc(sn.data.exportedAt || sn.name)}</option>`).join('')}</select>` : '';
    parts.push(layer('System prompt — as transcribed', `${sys.length} sections · exported ${esc(fmtTime(snap.exportedAt))} ${snapSel}`,
      `<p class="note">Transcribed by the model from its own context at export time; the model is the sensor here and transcription can be lossy. Not stored anywhere on disk by Claude Code.</p>` +
      sys.map((sec) => `<details class="msg"><summary><span class="role" style="color:var(--k-attach)">§</span><span class="prev">${esc(sec.title)}</span></summary><div class="body"><pre class="block">${esc(sec.content)}</pre></div></details>`).join(''), true));
    if ((snap.tools || []).length) {
      parts.push(layer('Tool definitions — as transcribed', `${snap.tools.length} tools`,
        snap.tools.map((t) => `<details class="msg"><summary><span class="role" style="color:var(--k-tool)">⚒</span><span class="prev">${esc(t.name)} — ${esc((t.description || '').slice(0, 90))}</span></summary><div class="body"><pre class="block">${esc(t.description || '')}\n\n${esc(JSON.stringify(t.schema ?? t.parameters ?? {}, null, 2))}</pre></div></details>`).join('')));
    }
    if ((snap.rules || []).length) {
      parts.push(layer('Rules & memory files', `${snap.rules.length} files`,
        snap.rules.map((f) => `<details class="msg"><summary><span class="role" style="color:var(--k-user)">✎</span><span class="prev">${esc(f.path)}</span></summary><div class="body"><pre class="block">${esc(f.content)}</pre></div></details>`).join('')));
    }
  } else {
    parts.push(layer('System prompt', 'no snapshot', `<p class="warn">No snapshot exported for this session — the system prompt and tool schemas exist only inside the model's context, so only <code>/context-export</code> run from within the live session can capture them.</p>`));
  }

  // dynamic session state (cumulative)
  const tools = [...st.deferredTools].sort();
  parts.push(layer('Deferred tools surfaced so far', `${tools.length} names · cumulative`,
    tools.length ? `<div class="chiplist">${tools.map((t) => `<span class="chip">${esc(t)}</span>`).join('')}</div>` : '<p class="hint">None yet at this point.</p>'));
  if (st.skillListing) {
    parts.push(layer('Skill listing in effect', `${st.skillListing.skillCount ?? '?'} skills${st.skillListing.isInitial ? ' · initial' : ''}`,
      `<pre class="block">${esc(String(st.skillListing.content || (st.skillListing.names || []).join('\n')))}</pre>`));
  }
  if (st.mcpInstructions.length) {
    parts.push(layer('MCP server instructions', `${st.mcpInstructions.length} delta(s)`,
      st.mcpInstructions.map((a) => `<pre class="block">${esc(String(a.content || JSON.stringify(a, null, 2)))}</pre>`).join('')));
  }
  if (st.outputStyle) {
    parts.push(layer('Output style (latest)', 'superseding',
      `<pre class="block">${esc(String(st.outputStyle.content || JSON.stringify(st.outputStyle, null, 2)))}</pre>`));
  }

  // message window
  const dropped = boundary?.compactMetadata;
  parts.push(layer('Messages in window', `${chain.length} records${boundary ? ' · after compaction' : ''}`,
    (boundary ? `<p class="note">Context was compacted here: ${fmtInt(dropped?.preTokens)} → ${fmtInt(dropped?.postTokens)} tokens (${esc(dropped?.trigger || '?')} trigger). Everything before the splice lives only in the summary below.</p>` : '') +
    chain.map((r) => renderMsg(r)).join(''), true));

  panel.innerHTML = parts.join('');
  const snapSel = document.getElementById('snapSel');
  if (snapSel) snapSel.addEventListener('change', (e) => { s.snapIdx = +e.target.value; select(s, s.sel, { keepSnap: true }); });
}

function renderMsg(r) {
  const kind = recKind(r);
  const cls = r.type === 'system' ? 'm-compact' : `m-${kind === 'tool' ? 'tool' : r.type}`;
  const role = r.type === 'attachment' ? (r.attachment?.type || 'attachment')
    : r.type === 'system' ? (r.subtype || 'system')
    : kind === 'tool' ? (r.type === 'user' ? 'tool result' : 'tool call')
    : r.type;
  let body = '';
  const c = r.message?.content;
  if (typeof c === 'string') body = `<pre class="block">${esc(c)}</pre>`;
  else if (Array.isArray(c)) {
    body = c.map((b) => {
      if (b.type === 'text') return `<div class="blk"><div class="blk-tag">text</div><pre class="block">${esc(b.text)}</pre></div>`;
      if (b.type === 'thinking') return `<div class="blk"><div class="blk-tag">thinking</div><pre class="block">${esc(b.thinking)}</pre></div>`;
      if (b.type === 'tool_use') return `<div class="blk"><div class="blk-tag">tool_use · ${esc(b.name)}</div><pre class="block">${esc(JSON.stringify(b.input, null, 2))}</pre></div>`;
      if (b.type === 'tool_result') {
        const inner = typeof b.content === 'string' ? b.content : Array.isArray(b.content) ? b.content.map((x) => x.text ?? JSON.stringify(x)).join('\n') : JSON.stringify(b.content);
        return `<div class="blk"><div class="blk-tag">tool_result${b.is_error ? ' · ERROR' : ''}</div><pre class="block">${esc(inner)}</pre></div>`;
      }
      return `<div class="blk"><div class="blk-tag">${esc(b.type)}</div><pre class="block">${esc(JSON.stringify(b, null, 2))}</pre></div>`;
    }).join('');
  } else if (r.type === 'attachment') body = `<pre class="block">${esc(JSON.stringify(r.attachment, null, 2))}</pre>`;
  else body = `<pre class="block">${esc(JSON.stringify(r.content ?? r, null, 2))}</pre>`;
  return `<details class="msg ${cls}"><summary><span class="role">${esc(role)}</span><span class="prev">${esc(recPreview(r))}</span></summary><div class="body">${body}</div></details>`;
}

function renderRecordTab(s, panel) {
  const rec = s.model.content[s.sel];
  panel.innerHTML = layer('Raw record', `#${s.sel + 1} · ${esc(rec.uuid || 'no uuid')}`,
    `<pre class="block" style="max-height:70vh">${esc(JSON.stringify(rec, null, 2))}</pre>`, true);
}

function renderSnapshotTab(s, panel) {
  if (!s.snapshots.length) {
    panel.innerHTML = layer('Snapshots', 'none', '<p class="hint">Run /context-export inside the live session to capture the in-context material.</p>', true);
    return;
  }
  panel.innerHTML = s.snapshots.map((sn, i) => {
    const d = sn.data;
    return layer(`Snapshot ${i + 1}`, esc(d.exportedAt || sn.name), `
      <div class="kv" style="margin-bottom:10px">
        <span class="k">model</span><span>${esc(d.model || '?')}</span>
        <span class="k">cli version</span><span>${esc(d.claudeCodeVersion || '?')}</span>
        <span class="k">anchored to</span><span>${esc(d.latestMessageUuid || '?')}</span>
        <span class="k">sections</span><span>${(d.systemPrompt || []).length} system-prompt · ${(d.tools || []).length} tools · ${(d.rules || []).length} rules files</span>
      </div>
      <pre class="block" style="max-height:60vh">${esc(JSON.stringify(d, null, 2))}</pre>`, i === s.snapIdx);
  }).join('');
}

function renderFilesTab(s, panel) {
  const files = s.manifest.files || [];
  if (!files.length) {
    panel.innerHTML = layer('Companion files', 'none', '<p class="hint">Subagent transcripts and other session files land here when exported.</p>', true);
    return;
  }
  panel.innerHTML = layer('Companion files', `${files.length}`, files.map((f) =>
    `<div style="font-family:var(--mono);font-size:12.5px;padding:2px 0"><a href="/api/sessions/${esc(s.id)}/files/${encodeURIComponent(f)}" target="_blank" rel="noopener">${esc(f)}</a></div>`).join(''), true);
}

toolUseResult.content:
/* Context Explorer SPA — parses raw session JSONL client-side and reconstructs
   the effective context window at any selected record.
   Reconstruction rules (derived from real Claude Code transcripts):
   - records link via parentUuid: context-at-point = parent-chain walk to root
   - compact_boundary records have parentUuid null, so the chain walk naturally
     stops at the live context's edge after a compaction
   - isSidechain records are subagent turns; never part of the main context
   - attachment kinds have different semantics: deferred_tools_delta accumulates,
     skill_listing / output_style / agent_listing supersede, mcp_instructions accumulates */
'use strict';

const KIND_COLORS = {
  user: '#4a8fdd',
  assistant: '#c08618',
  tool: '#8a5fe8',
  attach: '#27a578',
  event: '#d75d84',
};
const KIND_LABELS = { user: 'user', assistant: 'assistant', tool: 'tool i/o', attach: 'context Δ', event: 'event' };
const ACCENT = '#f0b429';

const $view = document.getElementById('view');
const state = { sessions: null, session: null };

// ---------- utilities ----------

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmtInt = (n) => (n == null ? '—' : Number(n).toLocaleString('en-US'));
const fmtTime = (ts) => (ts ? new Date(ts).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '—');
const el = (html) => { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstElementChild; };

async function jget(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  return r.json();
}
async function tget(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  return r.text();
}

// ---------- transcript model ----------

function parseTranscript(jsonl) {
  const records = [];
  for (const line of jsonl.split('\n')) {
    const t = line.trim();
    if (!t) continue;
    try { records.push(JSON.parse(t)); } catch { /* tolerate partial lines */ }
  }
  // content records: things that occupy (or mark the edge of) the context window
  const content = records.filter((r) =>
    r.type === 'user' || r.type === 'assistant' || r.type === 'attachment' ||
    (r.type === 'system' && r.subtype !== 'turn_duration'));
  const byUuid = new Map();
  for (const r of records) if (r.uuid) byUuid.set(r.uuid, r);
  return { records, content, byUuid };
}

function recKind(r) {
  if (r.type === 'attachment') return 'attach';
  if (r.type === 'system') return 'event';
  if (r.type === 'assistant') {
    const blocks = Array.isArray(r.message?.content) ? r.message.content : [];
    return blocks.length && blocks.every((b) => b.type === 'tool_use') ? 'tool' : 'assistant';
  }
  if (r.type === 'user') {
    const c = r.message?.content;
    if (Array.isArray(c) && c.length && c.every((b) => b.type === 'tool_result')) return 'tool';
    return 'user';
  }
  return 'event';
}

function recPreview(r) {
  if (r.type === 'attachment') {
    const a = r.attachment || {};
    if (a.type === 'deferred_tools_delta') return `deferred tools ${a.addedNames ? '+' + a.addedNames.length : ''}`;
    if (a.type === 'skill_listing') return `skill listing (${a.skillCount ?? '?'} skills)`;
    return a.type || 'attachment';
  }
  if (r.type === 'system') {
    if (r.subtype === 'compact_boundary') {
      const m = r.compactMetadata || {};
      return `COMPACTION ${fmtInt(m.preTokens)} → ${fmtInt(m.postTokens)} tok (${m.trigger || '?'})`;
    }
    return `${r.subtype || 'system'}: ${String(r.content ?? '').slice(0, 120)}`;
  }
  const c = r.message?.content;
  if (typeof c === 'string') return c.slice(0, 160);
  if (Array.isArray(c)) {
    for (const b of c) {
      if (b.type === 'text' && b.text) return b.text.slice(0, 160);
      if (b.type === 'tool_use') return `→ ${b.name}(${JSON.stringify(b.input ?? {}).slice(0, 110)})`;
      if (b.type === 'tool_result') {
        const inner = typeof b.content === 'string' ? b.content : Array.isArray(b.content) ? b.content.map((x) => x.text || '').join(' ') : '';
        return `← ${String(inner).slice(0, 150)}`;
      }
      if (b.type === 'thinking') return `[thinking] ${String(b.thinking || '').slice(0, 140)}`;
    }
  }
  return r.type;
}

function usageOf(r) {
  const u = r.message?.usage;
  if (!u) return null;
  const ctx = (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0);
  return { ctx, out: u.output_tokens || 0, u };
}

/* Effective context chain at a content record: walk parentUuid to root.
   Returns { chain, boundary } where boundary is the compact_boundary reached, if any. */
function chainAt(model, rec) {
  let start = rec;
  // meta/system rows without a chain link: anchor to the nearest prior linked record
  const idx = model.content.indexOf(rec);
  let i = idx;
  while (start && !start.uuid && i > 0) start = model.content[--i];
  const chain = [];
  const seen = new Set();
  let cur = start;
  while (cur && cur.uuid && !seen.has(cur.uuid)) {
    seen.add(cur.uuid);
    if (!cur.isSidechain) chain.push(cur);
    cur = cur.parentUuid ? model.byUuid.get(cur.parentUuid) : null;
  }
  chain.reverse();
  const boundary = chain.find((r) => r.type === 'system' && r.subtype === 'compact_boundary') || null;
  return { chain, boundary };
}

/* Session-lifetime attachment state accumulated chronologically up to (and incl.) index. */
function stateAt(model, idx) {
  const s = { deferredTools: new Set(), skillListing: null, mcpInstructions: [], outputStyle: null, agentListing: null, other: [] };
  for (let i = 0; i <= idx; i++) {
    const r = model.content[i];
    if (r.type !== 'attachment') continue;
    const a = r.attachment || {};
    switch (a.type) {
      case 'deferred_tools_delta':
        (a.addedNames || []).forEach((n) => s.deferredTools.add(n));
        (a.removedNames || []).forEach((n) => s.deferredTools.delete(n));
        break;
      case 'skill_listing': s.skillListing = a; break;
      case 'mcp_instructions_delta': s.mcpInstructions.push(a); break;
      case 'output_style': s.outputStyle = a; break;
      case 'agent_listing_delta': s.agentListing = a; break;
      default: s.other.push(a);
    }
  }
  return s;
}

/* Nearest assistant usage at-or-before index → context size readout. */
function tokensAt(model, idx) {
  for (let i = idx; i >= 0; i--) {
    const u = usageOf(model.content[i]);
    if (u) return { ...u, at: i };
  }
  return null;
}

// ---------- router ----------

window.addEventListener('hashchange', route);
route();

async function route() {
  const h = location.hash || '#/';
  try {
    const m = h.match(/^#\/s\/([A-Za-z0-9_-]+)/);
    if (m) await sessionView(m[1]);
    else await homeView();
  } catch (err) {
    $view.innerHTML = `<div class="empty-state"><h2>Something broke</h2><p class="warn">${esc(err.message)}</p></div>`;
  }
}

// ---------- home ----------

async function homeView() {
  document.title = 'Context Explorer';
  const sessions = await jget('/api/sessions');
  const cards = sessions.map((s) => {
    const title = s.customTitle || s.title || s.firstUserPrompt?.slice(0, 80) || s.sessionId;
    return `
    <a class="session-card" href="#/s/${esc(s.sessionId)}">
      <div class="row1">
        <span class="title">${esc(title)}</span>
        <span class="proj">${esc(s.project || s.cwd || '')}</span>
      </div>
      ${s.firstUserPrompt ? `<div class="prompt">${esc(s.firstUserPrompt.slice(0, 160))}</div>` : ''}
      <div class="stats">
        <span><b>${fmtInt(s.lineCount)}</b> records</span>
        <span><b>${fmtInt(s.snapshotCount)}</b> snapshot${s.snapshotCount === 1 ? '' : 's'}</span>
        <span><b>${fmtInt(s.compactBoundaries)}</b> compaction${s.compactBoundaries === 1 ? '' : 's'}</span>
        <span>${esc(fmtTime(s.firstTimestamp))} → ${esc(fmtTime(s.lastTimestamp))}</span>
        <span>cli ${esc(s.cliVersion || '?')}</span>
      </div>
    </a>`;
  }).join('');
  $view.innerHTML = `
    <header class="masthead">
      <h1>Context <span class="dim">Explorer</span></h1>
      <span class="sub">flight recorder for the Claude Code context window</span>
    </header>
    ${sessions.length ? `<div class="session-list">${cards}</div>` : `
    <div class="empty-state">
      <h2>No sessions imported yet</h2>
      <p>In any Claude Code session, run <code>/context-export</code>. The skill ships the
      session transcript here, along with an as-transcribed snapshot of the system prompt
      and loaded tool definitions — the parts that exist only inside the model's context.</p>
      <p>Then refresh this page.</p>
    </div>`}`;
}

// ---------- session ----------

async function sessionView(id) {
  $view.innerHTML = `<div class="crumb">loading transcript…</div>`;
  const [manifest, jsonl] = await Promise.all([
    jget(`/api/sessions/${id}`),
    tget(`/api/sessions/${id}/transcript`),
  ]);
  const model = parseTranscript(jsonl);
  const snapshots = [];
  for (const name of manifest.snapshots || []) {
    try { snapshots.push({ name, data: await jget(`/api/sessions/${id}/snapshots/${name}`) }); } catch {}
  }
  const title = manifest.customTitle || manifest.title || id;
  document.title = `${title} — Context Explorer`;

  const s = {
    id, manifest, model, snapshots,
    sel: model.content.length - 1,
    tab: 'context',
    showSidechain: true,
    snapIdx: snapshots.length - 1,
  };
  state.session = s;

  $view.innerHTML = `
    <div class="crumb"><a href="#/">← sessions</a> &nbsp;/&nbsp; <span style="font-family:var(--mono)">${esc(id)}</span></div>
    <header class="masthead" style="padding-top:6px">
      <h1 style="letter-spacing:.02em;text-transform:none;font-size:19px">${esc(title)}</h1>
      <span class="sub">${esc(manifest.project || manifest.cwd || '')}</span>
    </header>
    <div class="tape-wrap">
      <div class="tape-head">
        <span class="eyebrow">context tape — tokens in window · click to scrub</span>
        <span class="readout" id="readout"></span>
      </div>
      <canvas class="tape" id="tape" aria-label="Session timeline: context tokens per record; click to select a point in time"></canvas>
      <div class="tape-head" id="legend" style="padding-top:4px"></div>
    </div>
    <div class="session-body">
      <div class="rail">
        <div class="rail-head">
          <span class="eyebrow">records (${model.content.length})</span>
          <label><input type="checkbox" id="sidechainToggle" checked> subagent turns</label>
        </div>
        <div class="rail-list" id="rail"></div>
      </div>
      <div class="ctx-panel">
        <div class="tabs" id="tabs"></div>
        <div id="panel"></div>
      </div>
    </div>
    <div class="tape-tip" id="tapeTip"></div>`;

  document.getElementById('legend').innerHTML = Object.keys(KIND_COLORS).map((k) =>
    `<span class="readout"><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:${KIND_COLORS[k]};margin-right:5px"></span>${KIND_LABELS[k]}</span>`).join('') +
    `<span class="readout"><span style="display:inline-block;width:2px;height:11px;background:${KIND_COLORS.event};margin-right:5px"></span>compaction splice</span>`;

  document.getElementById('sidechainToggle').addEventListener('change', (e) => {
    s.showSidechain = e.target.checked;
    renderRail(s);
  });

  renderRail(s);
  initTape(s);
  select(s, s.sel, { scrollRail: true });
  window.addEventListener('resize', () => drawTape(s), { passive: true });
}

function select(s, idx, opts = {}) {
  s.sel = Math.max(0, Math.min(idx, s.model.content.length - 1));
  const rec = s.model.content[s.sel];
  // choose snapshot: latest whose exportedAt <= selected record time, else earliest after
  if (s.snapshots.length && !opts.keepSnap) {
    const t = rec.timestamp ? Date.parse(rec.timestamp) : Infinity;
    let pick = 0;
    s.snapshots.forEach((sn, i) => {
      const ts = Date.parse(sn.data.exportedAt || sn.data.receivedAt || 0);
      if (ts <= t || i === 0) pick = i;
    });
    s.snapIdx = pick;
  }
  document.querySelectorAll('.rec.sel').forEach((n) => n.classList.remove('sel'));
  const row = document.querySelector(`.rec[data-i="${s.sel}"]`);
  if (row) {
    row.classList.add('sel');
    if (opts.scrollRail) row.scrollIntoView({ block: 'center' });
  }
  drawTape(s);
  renderTabs(s);
  renderPanel(s);
  const u = tokensAt(s.model, s.sel);
  document.getElementById('readout').innerHTML =
    `rec <b>${s.sel + 1}</b>/${s.model.content.length}` +
    ` · <b>${u ? fmtInt(u.ctx) : '—'}</b> tok in window` +
    ` · ${esc(fmtTime(rec.timestamp))}`;
}

// ---------- record rail ----------

function renderRail(s) {
  const railEl = document.getElementById('rail');
  const frag = document.createDocumentFragment();
  s.model.content.forEach((r, i) => {
    if (r.isSidechain && !s.showSidechain) return;
    const kind = recKind(r);
    const compact = r.type === 'system' && r.subtype === 'compact_boundary';
    const row = el(`<div class="rec${r.isSidechain ? ' sidechain' : ''}${compact ? ' compact-row' : ''}" data-i="${i}" tabindex="0" role="button">
      <span class="dot" style="background:${KIND_COLORS[kind]}"></span>
      <span class="kind">${esc(r.type === 'attachment' ? (r.attachment?.type || 'attach').slice(0, 13) : (r.subtype || r.type))}</span>
      <span class="prev">${esc(recPreview(r))}</span>
    </div>`);
    row.addEventListener('click', () => select(s, i));
    row.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(s, i); } });
    frag.appendChild(row);
  });
  railEl.replaceChildren(frag);
}

// ---------- the tape (canvas instrument) ----------

function initTape(s) {
  const cv = document.getElementById('tape');
  const tip = document.getElementById('tapeTip');
  const idxFromEvent = (e) => {
    const r = cv.getBoundingClientRect();
    return Math.round(((e.clientX - r.left) / r.width) * (s.model.content.length - 1));
  };
  cv.addEventListener('click', (e) => select(s, idxFromEvent(e), { scrollRail: true }));
  cv.addEventListener('mousemove', (e) => {
    const i = Math.max(0, Math.min(idxFromEvent(e), s.model.content.length - 1));
    s.hover = i;
    drawTape(s);
    const rec = s.model.content[i];
    const u = tokensAt(s.model, i);
    tip.style.display = 'block';
    tip.style.left = Math.min(e.clientX + 14, window.innerWidth - 360) + 'px';
    tip.style.top = (e.clientY + 16) + 'px';
    tip.innerHTML = `<span class="k">#${i + 1} ${esc(rec.subtype || rec.type)}</span> · ${u ? fmtInt(u.ctx) + ' tok' : ''}<br>${esc(recPreview(rec).slice(0, 120))}`;
  });
  cv.addEventListener('mouseleave', () => { s.hover = null; tip.style.display = 'none'; drawTape(s); });
}

function drawTape(s) {
  const cv = document.getElementById('tape');
  if (!cv) return;
  const dpr = window.devicePixelRatio || 1;
  const W = cv.clientWidth, H = cv.clientHeight;
  cv.width = W * dpr; cv.height = H * dpr;
  const g = cv.getContext('2d');
  g.scale(dpr, dpr);
  g.clearRect(0, 0, W, H);

  const n = s.model.content.length;
  if (!n) return;
  const x = (i) => (i / Math.max(1, n - 1)) * (W - 8) + 4;
  const stripH = 16, chartH = H - stripH - 6;

  // token series: context size at each assistant record, stepped
  let maxTok = 1;
  const pts = [];
  let last = 0;
  s.model.content.forEach((r, i) => {
    const u = usageOf(r);
    if (u) { last = u.ctx; maxTok = Math.max(maxTok, u.ctx); }
    pts.push(last);
  });
  const y = (t) => chartH - (t / maxTok) * (chartH - 10) + 4;

  // area (single amber series)
  g.beginPath();
  g.moveTo(x(0), y(pts[0]));
  for (let i = 1; i < n; i++) g.lineTo(x(i), y(pts[i]));
  g.lineTo(x(n - 1), chartH + 4); g.lineTo(x(0), chartH + 4); g.closePath();
  g.fillStyle = 'rgba(192,134,24,0.22)';
  g.fill();
  g.beginPath();
  g.moveTo(x(0), y(pts[0]));
  for (let i = 1; i < n; i++) g.lineTo(x(i), y(pts[i]));
  g.strokeStyle = '#c08618'; g.lineWidth = 2; g.stroke();

  // tick strip by kind
  s.model.content.forEach((r, i) => {
    g.fillStyle = KIND_COLORS[recKind(r)];
    g.globalAlpha = r.isSidechain ? 0.35 : 0.9;
    g.fillRect(x(i) - 0.75, H - stripH, 1.5, stripH - 2);
    g.globalAlpha = 1;
  });

  // compaction splices: full-height, with a gap notch (shape = secondary encoding)
  s.model.content.forEach((r, i) => {
    if (r.type === 'system' && r.subtype === 'compact_boundary') {
      g.strokeStyle = KIND_COLORS.event; g.lineWidth = 2;
      g.setLineDash([5, 3]);
      g.beginPath(); g.moveTo(x(i), 2); g.lineTo(x(i), H - 2); g.stroke();
      g.setLineDash([]);
    }
  });

  // hover crosshair
  if (s.hover != null) {
    g.strokeStyle = 'rgba(223,228,236,0.35)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(x(s.hover), 0); g.lineTo(x(s.hover), H); g.stroke();
  }
  // selection cursor
  g.strokeStyle = ACCENT; g.lineWidth = 2;
  g.beginPath(); g.moveTo(x(s.sel), 0); g.lineTo(x(s.sel), H); g.stroke();
  g.fillStyle = ACCENT;
  g.beginPath(); g.moveTo(x(s.sel) - 5, 0); g.lineTo(x(s.sel) + 5, 0); g.lineTo(x(s.sel), 7); g.closePath(); g.fill();
}

// ---------- tabs + panels ----------

function renderTabs(s) {
  const tabs = [
    ['context', 'Context at this point'],
    ['record', 'Record'],
    ['snapshot', `Snapshot${s.snapshots.length ? ` (${s.snapshots.length})` : ''}`],
    ['files', `Files (${(s.manifest.files || []).length})`],
  ];
  document.getElementById('tabs').innerHTML = tabs.map(([k, label]) =>
    `<button data-tab="${k}" class="${s.tab === k ? 'on' : ''}">${label}</button>`).join('');
  document.querySelectorAll('#tabs button').forEach((b) =>
    b.addEventListener('click', () => { s.tab = b.dataset.tab; renderTabs(s); renderPanel(s); }));
}

function layer(title, badge, bodyHtml, open = false) {
  return `<details class="layer"${open ? ' open' : ''}>
    <summary><span class="eyebrow">${title}</span><span class="badge">${badge}</span></summary>
    <div class="body">${bodyHtml}</div>
  </details>`;
}

function renderPanel(s) {
  const panel = document.getElementById('panel');
  if (s.tab === 'record') return renderRecordTab(s, panel);
  if (s.tab === 'snapshot') return renderSnapshotTab(s, panel);
  if (s.tab === 'files') return renderFilesTab(s, panel);
  renderContextTab(s, panel);
}

function renderContextTab(s, panel) {
  const rec = s.model.content[s.sel];
  const { chain, boundary } = chainAt(s.model, rec);
  const st = stateAt(s.model, s.sel);
  const u = tokensAt(s.model, s.sel);
  const snap = s.snapshots[s.snapIdx]?.data;

  const parts = [];

  // token gauge
  parts.push(layer('Context window load', u ? `measured at record ${u.at + 1}` : 'no usage data yet', u ? `
    <div class="gauge">
      <span class="num">${fmtInt(u.ctx)}</span><span class="eyebrow">tokens in window</span>
      <span class="parts">cache-read ${fmtInt(u.u.cache_read_input_tokens)} · cache-write ${fmtInt(u.u.cache_creation_input_tokens)} · fresh in ${fmtInt(u.u.input_tokens)} · out ${fmtInt(u.u.output_tokens)}</span>
    </div>` : '<p class="hint">No assistant turn with usage before this point.</p>', true));

  // system prompt (from snapshot)
  if (snap) {
    const sys = snap.systemPrompt || [];
    const snapSel = s.snapshots.length > 1 ? `<select class="pill-select" id="snapSel">${s.snapshots.map((sn, i) =>
      `<option value="${i}"${i === s.snapIdx ? ' selected' : ''}>${esc(sn.data.exportedAt || sn.name)}</option>`).join('')}</select>` : '';
    parts.push(layer('System prompt — as transcribed', `${sys.length} sections · exported ${esc(fmtTime(snap.exportedAt))} ${snapSel}`,
      `<p class="note">Transcribed by the model from its own context at export time; the model is the sensor here and transcription can be lossy. Not stored anywhere on disk by Claude Code.</p>` +
      sys.map((sec) => `<details class="msg"><summary><span class="role" style="color:var(--k-attach)">§</span><span class="prev">${esc(sec.title)}</span></summary><div class="body"><pre class="block">${esc(sec.content)}</pre></div></details>`).join(''), true));
    if ((snap.tools || []).length) {
      parts.push(layer('Tool definitions — as transcribed', `${snap.tools.length} tools`,
        snap.tools.map((t) => `<details class="msg"><summary><span class="role" style="color:var(--k-tool)">⚒</span><span class="prev">${esc(t.name)} — ${esc((t.description || '').slice(0, 90))}</span></summary><div class="body"><pre class="block">${esc(t.description || '')}\n\n${esc(JSON.stringify(t.schema ?? t.parameters ?? {}, null, 2))}</pre></div></details>`).join('')));
    }
    if ((snap.rules || []).length) {
      parts.push(layer('Rules & memory files', `${snap.rules.length} files`,
        snap.rules.map((f) => `<details class="msg"><summary><span class="role" style="color:var(--k-user)">✎</span><span class="prev">${esc(f.path)}</span></summary><div class="body"><pre class="block">${esc(f.content)}</pre></div></details>`).join('')));
    }
  } else {
    parts.push(layer('System prompt', 'no snapshot', `<p class="warn">No snapshot exported for this session — the system prompt and tool schemas exist only inside the model's context, so only <code>/context-export</code> run from within the live session can capture them.</p>`));
  }

  // dynamic session state (cumulative)
  const tools = [...st.deferredTools].sort();
  parts.push(layer('Deferred tools surfaced so far', `${tools.length} names · cumulative`,
    tools.length ? `<div class="chiplist">${tools.map((t) => `<span class="chip">${esc(t)}</span>`).join('')}</div>` : '<p class="hint">None yet at this point.</p>'));
  if (st.skillListing) {
    parts.push(layer('Skill listing in effect', `${st.skillListing.skillCount ?? '?'} skills${st.skillListing.isInitial ? ' · initial' : ''}`,
      `<pre class="block">${esc(String(st.skillListing.content || (st.skillListing.names || []).join('\n')))}</pre>`));
  }
  if (st.mcpInstructions.length) {
    parts.push(layer('MCP server instructions', `${st.mcpInstructions.length} delta(s)`,
      st.mcpInstructions.map((a) => `<pre class="block">${esc(String(a.content || JSON.stringify(a, null, 2)))}</pre>`).join('')));
  }
  if (st.outputStyle) {
    parts.push(layer('Output style (latest)', 'superseding',
      `<pre class="block">${esc(String(st.outputStyle.content || JSON.stringify(st.outputStyle, null, 2)))}</pre>`));
  }

  // message window
  const dropped = boundary?.compactMetadata;
  parts.push(layer('Messages in window', `${chain.length} records${boundary ? ' · after compaction' : ''}`,
    (boundary ? `<p class="note">Context was compacted here: ${fmtInt(dropped?.preTokens)} → ${fmtInt(dropped?.postTokens)} tokens (${esc(dropped?.trigger || '?')} trigger). Everything before the splice lives only in the summary below.</p>` : '') +
    chain.map((r) => renderMsg(r)).join(''), true));

  panel.innerHTML = parts.join('');
  const snapSel = document.getElementById('snapSel');
  if (snapSel) snapSel.addEventListener('change', (e) => { s.snapIdx = +e.target.value; select(s, s.sel, { keepSnap: true }); });
}

function renderMsg(r) {
  const kind = recKind(r);
  const cls = r.type === 'system' ? 'm-compact' : `m-${kind === 'tool' ? 'tool' : r.type}`;
  const role = r.type === 'attachment' ? (r.attachment?.type || 'attachment')
    : r.type === 'system' ? (r.subtype || 'system')
    : kind === 'tool' ? (r.type === 'user' ? 'tool result' : 'tool call')
    : r.type;
  let body = '';
  const c = r.message?.content;
  if (typeof c === 'string') body = `<pre class="block">${esc(c)}</pre>`;
  else if (Array.isArray(c)) {
    body = c.map((b) => {
      if (b.type === 'text') return `<div class="blk"><div class="blk-tag">text</div><pre class="block">${esc(b.text)}</pre></div>`;
      if (b.type === 'thinking') return `<div class="blk"><div class="blk-tag">thinking</div><pre class="block">${esc(b.thinking)}</pre></div>`;
      if (b.type === 'tool_use') return `<div class="blk"><div class="blk-tag">tool_use · ${esc(b.name)}</div><pre class="block">${esc(JSON.stringify(b.input, null, 2))}</pre></div>`;
      if (b.type === 'tool_result') {
        const inner = typeof b.content === 'string' ? b.content : Array.isArray(b.content) ? b.content.map((x) => x.text ?? JSON.stringify(x)).join('\n') : JSON.stringify(b.content);
        return `<div class="blk"><div class="blk-tag">tool_result${b.is_error ? ' · ERROR' : ''}</div><pre class="block">${esc(inner)}</pre></div>`;
      }
      return `<div class="blk"><div class="blk-tag">${esc(b.type)}</div><pre class="block">${esc(JSON.stringify(b, null, 2))}</pre></div>`;
    }).join('');
  } else if (r.type === 'attachment') body = `<pre class="block">${esc(JSON.stringify(r.attachment, null, 2))}</pre>`;
  else body = `<pre class="block">${esc(JSON.stringify(r.content ?? r, null, 2))}</pre>`;
  return `<details class="msg ${cls}"><summary><span class="role">${esc(role)}</span><span class="prev">${esc(recPreview(r))}</span></summary><div class="body">${body}</div></details>`;
}

function renderRecordTab(s, panel) {
  const rec = s.model.content[s.sel];
  panel.innerHTML = layer('Raw record', `#${s.sel + 1} · ${esc(rec.uuid || 'no uuid')}`,
    `<pre class="block" style="max-height:70vh">${esc(JSON.stringify(rec, null, 2))}</pre>`, true);
}

function renderSnapshotTab(s, panel) {
  if (!s.snapshots.length) {
    panel.innerHTML = layer('Snapshots', 'none', '<p class="hint">Run /context-export inside the live session to capture the in-context material.</p>', true);
    return;
  }
  panel.innerHTML = s.snapshots.map((sn, i) => {
    const d = sn.data;
    return layer(`Snapshot ${i + 1}`, esc(d.exportedAt || sn.name), `
      <div class="kv" style="margin-bottom:10px">
        <span class="k">model</span><span>${esc(d.model || '?')}</span>
        <span class="k">cli version</span><span>${esc(d.claudeCodeVersion || '?')}</span>
        <span class="k">anchored to</span><span>${esc(d.latestMessageUuid || '?')}</span>
        <span class="k">sections</span><span>${(d.systemPrompt || []).length} system-prompt · ${(d.tools || []).length} tools · ${(d.rules || []).length} rules files</span>
      </div>
      <pre class="block" style="max-height:60vh">${esc(JSON.stringify(d, null, 2))}</pre>`, i === s.snapIdx);
  }).join('');
}

function renderFilesTab(s, panel) {
  const files = s.manifest.files || [];
  if (!files.length) {
    panel.innerHTML = layer('Companion files', 'none', '<p class="hint">Subagent transcripts and other session files land here when exported.</p>', true);
    return;
  }
  panel.innerHTML = layer('Companion files', `${files.length}`, files.map((f) =>
    `<div style="font-family:var(--mono);font-size:12.5px;padding:2px 0"><a href="/api/sessions/${esc(s.id)}/files/${encodeURIComponent(f)}" target="_blank" rel="noopener">${esc(f)}</a></div>`).join(''), true);
}

