43	// ---------- transcript model ----------
44	
45	function parseTranscript(jsonl) {
46	  const records = [];
47	  for (const line of jsonl.split('\n')) {
48	    const t = line.trim();
49	    if (!t) continue;
50	    try { records.push(JSON.parse(t)); } catch { /* tolerate partial lines */ }
51	  }
52	  // content records: things that occupy (or mark the edge of) the context window
53	  const content = records.filter((r) =>
54	    r.type === 'user' || r.type === 'assistant' || r.type === 'attachment' ||
55	    (r.type === 'system' && r.subtype !== 'turn_duration'));
56	  const byUuid = new Map();
57	  for (const r of records) if (r.uuid) byUuid.set(r.uuid, r);
58	  return { records, content, byUuid };
59	}
