61	function recKind(r) {
62	  if (r.type === 'attachment') return 'attach';
63	  if (r.type === 'system') return 'event';
64	  if (r.type === 'assistant') {
65	    const blocks = Array.isArray(r.message?.content) ? r.message.content : [];
66	    return blocks.length && blocks.every((b) => b.type === 'tool_use') ? 'tool' : 'assistant';
67	  }
68	  if (r.type === 'user') {
69	    const c = r.message?.content;
70	    if (Array.isArray(c) && c.length && c.every((b) => b.type === 'tool_result')) return 'tool';
71	    return 'user';
72	  }
73	  return 'event';
74	}
75	
76	function recPreview(r) {
77	  if (r.type === 'attachment') {
78	    const a = r.attachment || {};
