80	    if (a.type === 'skill_listing') return `skill listing (${a.skillCount ?? '?'} skills)`;
81	    return a.type || 'attachment';
82	  }
83	  if (r.type === 'system') {
84	    if (r.subtype === 'compact_boundary') {
85	      const m = r.compactMetadata || {};
86	      return `COMPACTION ${fmtInt(m.preTokens)} → ${fmtInt(m.postTokens)} tok (${m.trigger || '?'})`;
87	    }
88	    return `${r.subtype || 'system'}: ${String(r.content ?? '').slice(0, 120)}`;
89	  }
90	  const c = r.message?.content;
91	  if (typeof c === 'string') return c.slice(0, 160);
92	  if (Array.isArray(c)) {
93	    for (const b of c) {
94	      if (b.type === 'text' && b.text) return b.text.slice(0, 160);
95	      if (b.type === 'tool_use') return `→ ${b.name}(${JSON.stringify(b.input ?? {}).slice(0, 110)})`;
96	      if (b.type === 'tool_result') {
