99	      }
100	      if (b.type === 'thinking') return `[thinking] ${String(b.thinking || '').slice(0, 140)}`;
101	    }
102	  }
103	  return r.type;
104	}
105	
106	function usageOf(r) {
107	  const u = r.message?.usage;
108	  if (!u) return null;
109	  const ctx = (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0);
110	  return { ctx, out: u.output_tokens || 0, u };
111	}
112	
113	/* Effective context chain at a content record: walk parentUuid to root.
114	   Returns { chain, boundary } where boundary is the compact_boundary reached, if any. */
115	function chainAt(model, rec) {
116	  let start = rec;
117	  // meta/system rows without a chain link: anchor to the nearest prior linked record
118	  const idx = model.content.indexOf(rec);
119	  let i = idx;
120	  while (start && !start.uuid && i > 0) start = model.content[--i];
121	  const chain = [];
122	  const seen = new Set();
123	  let cur = start;
124	  while (cur && cur.uuid && !seen.has(cur.uuid)) {
125	    seen.add(cur.uuid);
126	    if (!cur.isSidechain) chain.push(cur);
127	    cur = cur.parentUuid ? model.byUuid.get(cur.parentUuid) : null;
128	  }
129	  chain.reverse();
130	  const boundary = chain.find((r) => r.type === 'system' && r.subtype === 'compact_boundary') || null;
131	  return { chain, boundary };
132	}
133	
134	/* Session-lifetime attachment state accumulated chronologically up to (and incl.) index. */
135	function stateAt(model, idx) {
136	  const s = { deferredTools: new Set(), skillListing: null, mcpInstructions: [], outputStyle: null, agentListing: null, other: [] };
137	  for (let i = 0; i <= idx; i++) {
138	    const r = model.content[i];
139	    if (r.type !== 'attachment') continue;
140	    const a = r.attachment || {};
141	    switch (a.type) {
142	      case 'deferred_tools_delta':
143	        (a.addedNames || []).forEach((n) => s.deferredTools.add(n));
144	        (a.removedNames || []).forEach((n) => s.deferredTools.delete(n));
145	        break;
146	      case 'skill_listing': s.skillListing = a; break;
147	      case 'mcp_instructions_delta': s.mcpInstructions.push(a); break;
148	      case 'output_style': s.outputStyle = a; break;
149	      case 'agent_listing_delta': s.agentListing = a; break;
150	      default: s.other.push(a);
151	    }
152	  }
153	  return s;
154	}
155	
156	/* Nearest assistant usage at-or-before index → context size readout. */
157	function tokensAt(model, idx) {
158	  for (let i = idx; i >= 0; i--) {
159	    const u = usageOf(model.content[i]);
